import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const tradeErrorRepairApi = createApi({
    reducerPath: 'tradeErrorRepairApi',
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        // Закриває неузгоджені угоди статусом «repaired» — нічого не видаляє.
        repairTradeErrors: builder.mutation({
            query: () => ({
                url: '/trades/errors/repair',
                method: RequestMethods.POST,
            }),
        }),
    }),
});
export const { useRepairTradeErrorsMutation, } = tradeErrorRepairApi;
