// Логіка вибору порогу на ступінчастій шкалі нейрона — без React.
//
// Відносна метрика сигналу (рух чи напрямок, % шкали нейрона) приймає лише
// кілька значень — сходинки кривої калібровки: напр. лонги 0 / 23 / 25 / 34 /
// 61 / 100. Поріг F пропускає сходинки зі значенням ≥ F, тож будь-який поріг
// між двома сходинками діє так само, як поріг на верхній із них. Тому
// повзунок «магнітиться» лише до сходинок: поріг = значення сходинки.
//
// Смуга — «мозаїка потоку»: кожна сходинка — блок шириною в її частку потоку.
// Найменша ширина блоку, щоб у вузьку сходинку можна було влучити.
export const MIN_BLOCK_WIDTH = 6;
// Сходинки за зростанням значення, без дублікатів.
export const sortSteps = (steps) => {
    const byValue = new Map();
    steps.forEach((step) => {
        if (!byValue.has(step.value))
            byValue.set(step.value, step);
    });
    return [...byValue.values()].sort((a, b) => a.value - b.value);
};
// Поріг, що не лежить на сходинці (збережений колись «76»), діє як найнижча
// сходинка, не нижча за нього; вище за всі — не пропускає нічого.
export const effectiveStep = (steps, floor) => sortSteps(steps).find((step) => step.value >= floor) ?? null;
// Сусідня сходинка: для клавіш ←/→ (delta −1 / +1). Від порогу поза
// сходинками рухаємось від тієї, що діє.
export const neighbourStep = (steps, floor, delta) => {
    const sorted = sortSteps(steps);
    if (!sorted.length)
        return floor;
    const current = effectiveStep(sorted, floor);
    const index = current ? sorted.indexOf(current) : sorted.length;
    const next = Math.min(sorted.length - 1, Math.max(0, index + delta));
    return sorted[next].value;
};
// Частка потоку, що проходить поріг (сума share сходинок ≥ поріг); null —
// коли про потік нічого не відомо.
export const passingShare = (steps, floor) => {
    if (!steps.some((step) => step.share !== undefined))
        return null;
    return sortSteps(steps)
        .filter((step) => step.value >= floor)
        .reduce((sum, step) => sum + (step.share ?? 0), 0);
};
// Блоки смуги: ширина ∝ частці потоку (не менше MIN_BLOCK_WIDTH), разом рівно
// 100. Без share — порівну.
export const mosaicBlocks = (steps) => {
    const sorted = sortSteps(steps);
    if (!sorted.length)
        return [];
    const known = sorted.every((step) => step.share !== undefined);
    const raw = sorted.map((step) => (known ? Math.max(step.share ?? 0, 0) : 1));
    const total = raw.reduce((a, b) => a + b, 0) || sorted.length;
    const lifted = raw.map((weight) => Math.max((weight / total) * 100, MIN_BLOCK_WIDTH));
    const liftedTotal = lifted.reduce((a, b) => a + b, 0);
    let start = 0;
    return sorted.map((step, index) => {
        const width = (lifted[index] / liftedTotal) * 100;
        const block = { ...step, start, width };
        start += width;
        return block;
    });
};
// Позиція порогу на смузі — ліва межа блоку сходинки, що діє.
export const mosaicPosition = (blocks, floor) => {
    const block = blocks.find((b) => b.value >= floor);
    return block ? block.start : 100;
};
// Блок під точкою смуги (0..100): поріг = значення цього блоку.
export const mosaicStepAt = (blocks, position) => {
    if (!blocks.length)
        return null;
    const hit = blocks.find((b) => position < b.start + b.width) ?? blocks[blocks.length - 1];
    return hit.value;
};
export const formatPercent = (fraction, digits = 1) => (`${(fraction * 100).toFixed(digits)}%`);
